def frequencyStackPops(ops):
    freq = {}
    groups = {}
    maxf = 0
    out = []
    for t, x in ops:
        if t == 1:
            f = freq.get(x, 0) + 1
            freq[x] = f
            groups.setdefault(f, []).append(x)
            if f > maxf:
                maxf = f
        else:
            x = groups[maxf].pop()
            freq[x] -= 1
            if not groups[maxf]:
                maxf -= 1
            out.append(x)
    return out
